CREATE COLUMN TABLE "TEST_AP"."ACS1" ("Code" NVARCHAR(20) NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "DprAreaID" NVARCHAR(15) NOT NULL , "Active" NVARCHAR(1) DEFAULT 'Y', "AcctDtn" NVARCHAR(15), "DprTypID" NVARCHAR(15), "UseLife" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ACS1_UNIQUE" ON "TEST_AP"."ACS1" ( "Code" ASC, "DprAreaID" ASC )